import{z as o,x as i,o as r,c as d,q as n,j as B,D as e,d as t,s as A,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"时间片轮转","description":"","frontmatter":{"title":"时间片轮转","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rr-quantum.md","filePath":"cs/rr-quantum.md","lastUpdated":1791063341000}'),p={name:"cs/rr-quantum.md"};function m(F,a,c,u,C,q){const s=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=n('<h1 id="时间片轮转" tabindex="-1">时间片轮转 <a class="header-anchor" href="#时间片轮转" aria-label="Permalink to &quot;时间片轮转&quot;">​</a></h1><div class="epigraph"><p>轮转给每个可运行任务一个量子；用完则排到队尾。片太短切换税吃掉吞吐，片太长退化成 FCFS。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/fcfs-sjf">上一课</a>的非抢占策略对交互没有响应上限。时钟中断已经能把 CPU 抢回来。<a href="/cs/scheduling-metrics">调度指标</a>里响应时间正是为这种抢占准备的。缺口是 <strong>RR</strong>：runqueue 当环形 FIFO，每条任务最多连续跑一个量子 \\(q\\)。本课钉量子与指标的折中，不引入多级队列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>击键处理若要等当前编译突发结束，响应不可接受。RR：时钟减量子，到零则切换并把当前任务接到队尾。I/O 型往往用不完 \\(q\\) 就阻塞，等于自动偏向短突发。缺口不是 SJF 的估计，而是用<strong>固定抢占周期</strong>逼近公平的人次均等。<span class="marginnote">直觉类比：RR 就像幼儿园排队玩秋千——每人荡固定时间（一个量子），计时器一响必须把秋千让给队尾的下一个人，自己重新去排队尾。人越多，同一孩子两次上秋千的间隔越长，但没人能一直霸着不让。</span></p><p><span class="marginnote">\\(n\\) 个可运行任务时，一条任务最迟大约 \\((n-1)q\\) 后再摸到 CPU（忽略切换税）。这是响应的上界直觉，不是硬实时保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(q\\)。相对一次突发：若 \\(q\\) 大于绝大多数突发，RR ≈ FCFS；若 \\(q\\) 接近一次内核切换的代价，利用率塌掉。教材常用几十毫秒量级作讨论，不是定律。切换仍走<a href="/cs/context-switch">上下文切换</a>；FPU 惰性在 RR 下更值钱，因为切得勤。<span class="marginnote">数字实例：设单次上下文切换约花 10 μs。\\(q=10\\) ms 时，切换税占比约 0.1%，几乎免费；把 \\(q\\) 压到 100 μs，占比涨到 10%；再压到 20 μs，一半的 CPU 时间在切换而非干活。量子越短，税不是线性变贵，是占比指数式恶化。</span></p>',8)),(r(),B(l,null,{default:e(()=>[A(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RQ%5B%22FIFO%20%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%22%5D%20--%3E%20RUN%5B%22%E8%B7%91%E8%87%B3%E5%A4%9A%20q%22%5D%0A%20%20RUN%20--%3E%20EX%5B%22%E7%94%A8%E5%B0%BD%3A%20%E5%88%B0%E9%98%9F%E5%B0%BE%22%5D%0A%20%20RUN%20--%3E%20BL%5B%22%E9%98%BB%E5%A1%9E%3A%20%E7%A6%BB%E5%BC%80%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"唤醒入队位置：队尾（常见）或按规则插队；本课默认队尾，以免刚唤醒的立刻垄断。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[t("RR 把公平定义成人次轮流，不认权重：后台编译与前台击键同一 \\(q\\)。这正是后课 CFS 要改的点，本课先把「无权重轮转」钉死。对纯 CPU 型集合，平均等待往往差于 SJF，但响应方差小。传送带效应被量子切开。"),E("span",{class:"marginnote"},"常见误区：初学者容易以为 RR 的平均等待时间一定比 SJF 短——恰好相反，RR 用更高的平均等待换来了更小的响应方差：每个任务都「不久就会轮到」，但短任务可能被排在一堆长任务各切一刀的后面。RR 买的是「没有饿死」，不是「最快完成」。")],-1)),(r(),B(l,null,{default:e(()=>[A(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20PICK%5B%22%E9%97%AE%E9%A2%98%EF%BC%9A%E9%87%8F%E5%AD%90%20q%20%E8%AF%A5%E5%8F%96%E5%A4%9A%E5%A4%A7%22%5D%20--%3E%20CMP%7B%22q%20%E4%B8%8E%E5%85%B8%E5%9E%8B%E7%AA%81%E5%8F%91%E9%95%BF%E5%BA%A6%E7%9B%B8%E6%AF%94%22%7D%0A%20%20CMP%20--%20%22q%20%E8%BF%9C%E5%A4%A7%E4%BA%8E%E7%BB%9D%E5%A4%A7%E5%A4%9A%E6%95%B0%E7%AA%81%E5%8F%91%22%20--%3E%20F1%5B%22%E9%80%80%E5%8C%96%E6%88%90%20FCFS%EF%BC%9A%E4%BA%A4%E4%BA%92%E5%93%8D%E5%BA%94%E5%9B%9E%E5%88%B0%E8%80%81%E9%97%AE%E9%A2%98%22%5D%0A%20%20CMP%20--%20%22q%20%E6%8E%A5%E8%BF%91%E4%B8%80%E6%AC%A1%E5%88%87%E6%8D%A2%E7%9A%84%E4%BB%A3%E4%BB%B7%22%20--%3E%20F2%5B%22%E5%88%87%E6%8D%A2%E7%A8%8E%E5%90%83%E6%8E%89%E5%88%A9%E7%94%A8%E7%8E%87%22%5D%0A%20%20CMP%20--%20%22q%20%E8%90%BD%E5%9C%A8%E4%B8%AD%E9%97%B4%E5%9C%B0%E5%B8%A6%22%20--%3E%20F3%5B%22%E8%BD%AE%E6%B5%81%E5%85%AC%E5%B9%B3%E4%B8%94%E5%BC%80%E9%94%80%E5%8F%AF%E5%AE%B9%E5%BF%8D%22%5D%0A%20%20F3%20--%3E%20TUNE%5B%22%E9%9A%8F%E4%BB%BB%E5%8A%A1%E6%9E%84%E6%88%90%E9%87%8D%E8%B0%83%EF%BC%9A%E6%B2%A1%E6%9C%89%E6%99%AE%E9%80%82%E5%B8%B8%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>与 idle：只有 idle 可跑时不轮转它与自己。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 POSIX <code>SCHED_RR</code> 的实时轮转与分时 RR 混成一种队列。也不把动态调整 \\(q\\) 的启发式写完。优先级尚未进场；所有人同一档。</p><p>后课默认：固定量子改善响应、人次公平。要用近期行为把任务分进不同量子档，下一课讲多级反馈队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RR：量子到则队尾；响应有与 \\(n q\\) 相关的直觉上界。</li><li>\\(q\\) 在切换税与 FCFS 化之间折中；无权重。</li><li>按行为分档是 MLFQ 的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',6))])}const f=o(p,[["render",m]]);export{R as __pageData,f as default};
